mapper.select:
/* com.portal.user.banner.BannerMapper.selectBannerList */ SELECT BANNER_ID, BANNER_NM, LINK_URL, BANNER_IMAGE, BANNER_IMAGE_FILE, BANNER_DC, SORT_ORDR, REFLCT_AT, FRST_REGISTER_ID, DATE_FORMAT(FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM FROM LETTNBANNER WHERE 1 = 1
AND BANNER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.update:
/* com.portal.user.banner.BannerMapper.updateBanner */ UPDATE LETTNBANNER SET BANNER_NM = #{bannerNm}, LINK_URL = #{linkUrl},
BANNER_IMAGE = #{bannerImage}, BANNER_IMAGE_FILE = #{bannerImageFile},
BANNER_DC = #{bannerDc}, SORT_ORDR = #{sortOrdr}, REFLCT_AT = #{reflctAt}, LAST_UPDUSR_ID = #{userId}, LAST_UPDT_PNTTM = NOW() WHERE BANNER_ID = #{bannerId}
